#include <pthread.h>
#include <stdio.h>

int main() {
    pthread_key_t key;
    int ret = pthread_key_create(&key, NULL);
    if (ret != 0) {
        printf("Error creating key\n");
        return 1;
    }
    ret = pthread_key_delete(key);
    if (ret != 0) {
        printf("Error deleting key\n");
        return 1;
    }
    printf("Key deleted successfully\n");
    return 0;
}
